//! Original Rust JavaScript runtime, implementing a deliberately growing ECMAScript subset.
mod lexer;mod parser;
use std::collections::HashMap;
pub use lexer::{LexError,Token,TokenKind};use parser::{Expr,ParseError,Parser,Stmt};
#[derive(Clone,Debug,PartialEq)]pub enum Value{Number(f64),String(String),Boolean(bool),Null,Undefined}
impl Value{fn truthy(&self)->bool{match self{Self::Boolean(v)=>*v,Self::Null|Self::Undefined=>false,Self::Number(n)=>*n!=0.0&&!n.is_nan(),Self::String(s)=>!s.is_empty()}}fn display(&self)->String{match self{Self::Number(n)if n.fract()==0.0=>format!("{n:.0}"),Self::Number(n)=>n.to_string(),Self::String(s)=>s.clone(),Self::Boolean(v)=>v.to_string(),Self::Null=>"null".into(),Self::Undefined=>"undefined".into()}}}
#[derive(Debug,PartialEq)]pub enum EngineError{Lex(LexError),Parse(ParseError),Type(String),Reference(String),Syntax(String)}
impl std::fmt::Display for EngineError{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{match self{Self::Lex(e)=>write!(f,"lex error: {e}"),Self::Parse(e)=>write!(f,"parse error: {e}"),Self::Type(s)=>write!(f,"type error: {s}"),Self::Reference(s)=>write!(f,"reference error: {s}"),Self::Syntax(s)=>write!(f,"syntax error: {s}")}}}impl std::error::Error for EngineError{}impl From<LexError> for EngineError{fn from(e:LexError)->Self{Self::Lex(e)}}impl From<ParseError> for EngineError{fn from(e:ParseError)->Self{Self::Parse(e)}}
#[derive(Clone,Debug)]struct Binding{value:Value,constant:bool}
#[derive(Clone)]struct Function{params:Vec<String>,body:Vec<Stmt>}
enum Flow{Value(Value),Return(Value)}
pub struct Runtime{scopes:Vec<HashMap<String,Binding>>,functions:HashMap<String,Function>,output:Vec<String>,call_depth:usize}
impl Default for Runtime{fn default()->Self{Self{scopes:vec![HashMap::new()],functions:HashMap::new(),output:Vec::new(),call_depth:0}}}
impl Runtime{
pub fn new()->Self{Self::default()}
pub fn execute(&mut self,source:&str)->Result<Value,EngineError>{let p=Parser::new(lexer::tokenize(source)?).parse_program()?;match self.execute_statements(p)?{Flow::Value(v)=>Ok(v),Flow::Return(_)=>Err(EngineError::Syntax("return outside a function".into()))}}
pub fn take_output(&mut self)->Vec<String>{std::mem::take(&mut self.output)}
pub fn get_global(&self,name:&str)->Option<&Value>{self.scopes.first()?.get(name).map(|b|&b.value)}
fn execute_statements(&mut self,ss:Vec<Stmt>)->Result<Flow,EngineError>{let mut last=Value::Undefined;for s in ss{match self.execute_statement(s)?{Flow::Value(v)=>last=v,ret@Flow::Return(_)=>return Ok(ret)}}Ok(Flow::Value(last))}
fn execute_scoped(&mut self,ss:Vec<Stmt>)->Result<Flow,EngineError>{self.scopes.push(HashMap::new());let result=self.execute_statements(ss);self.scopes.pop();result}
fn execute_statement(&mut self,s:Stmt)->Result<Flow,EngineError>{match s{
Stmt::Expression(e)=>Ok(Flow::Value(self.evaluate(e)?)),
Stmt::Declaration{name,value,constant}=>{if self.scopes.last().is_some_and(|s|s.contains_key(&name)){return Err(EngineError::Syntax(format!("'{name}' has already been declared in this scope")))}let v=self.evaluate(value)?;self.scopes.last_mut().unwrap().insert(name,Binding{value:v.clone(),constant});Ok(Flow::Value(v))}
Stmt::Block(b)=>self.execute_scoped(b),
Stmt::If{condition,then_branch,else_branch}=>if self.evaluate(condition)?.truthy(){self.execute_scoped(then_branch)}else if let Some(b)=else_branch{self.execute_scoped(b)}else{Ok(Flow::Value(Value::Undefined))},
Stmt::While{condition,body}=>{let mut last=Value::Undefined;while self.evaluate(condition.clone())?.truthy(){match self.execute_scoped(body.clone())?{Flow::Value(v)=>last=v,ret@Flow::Return(_)=>return Ok(ret)}}Ok(Flow::Value(last))},
Stmt::Function{name,params,body}=>{if self.functions.contains_key(&name)||self.scopes[0].contains_key(&name){return Err(EngineError::Syntax(format!("'{name}' has already been declared")))}self.functions.insert(name,Function{params,body});Ok(Flow::Value(Value::Undefined))},
Stmt::Return(e)=>{if self.call_depth==0{return Err(EngineError::Syntax("return outside a function".into()))}Ok(Flow::Return(if let Some(e)=e{self.evaluate(e)?}else{Value::Undefined}))}
}}
fn evaluate(&mut self,e:Expr)->Result<Value,EngineError>{match e{
Expr::Literal(v)=>Ok(v),Expr::Identifier(n)=>self.lookup(&n).map(|b|b.value.clone()).ok_or_else(||EngineError::Reference(format!("{n} is not defined"))),
Expr::Assign{name,value}=>{let i=self.scopes.iter().rposition(|s|s.contains_key(&name)).ok_or_else(||EngineError::Reference(format!("{name} is not defined")))?;if self.scopes[i][&name].constant{return Err(EngineError::Type(format!("assignment to constant variable '{name}'")))}let v=self.evaluate(*value)?;self.scopes[i].get_mut(&name).unwrap().value=v.clone();Ok(v)},
Expr::Unary{op,value}=>{let v=self.evaluate(*value)?;match op.as_str(){"!"=>Ok(Value::Boolean(!v.truthy())),"+"=>self.number(v).map(Value::Number),"-"=>self.number(v).map(|n|Value::Number(-n)),_=>Err(EngineError::Syntax(format!("unsupported unary operator {op}")))}},
Expr::Binary{op,left,right}=>{let a=self.evaluate(*left)?;if op=="&&"&&!a.truthy(){return Ok(a)}if op=="||"&&a.truthy(){return Ok(a)}let b=self.evaluate(*right)?;self.binary(&op,a,b)},
Expr::Call{name,args}=>{let fun=self.functions.get(&name).cloned().ok_or_else(||EngineError::Reference(format!("{name} is not defined")))?;if self.call_depth>=512{return Err(EngineError::Range("maximum call depth exceeded".into()))}let mut values=Vec::with_capacity(args.len());for a in args{values.push(self.evaluate(a)?)}self.call_depth+=1;self.scopes.push(HashMap::new());for (i,p) in fun.params.iter().enumerate(){self.scopes.last_mut().unwrap().insert(p.clone(),Binding{value:values.get(i).cloned().unwrap_or(Value::Undefined),constant:false});}let result=self.execute_statements(fun.body);self.scopes.pop();self.call_depth-=1;match result?{Flow::Value(_)=>Ok(Value::Undefined),Flow::Return(v)=>Ok(v)}}
}}
fn lookup(&self,n:&str)->Option<&Binding>{self.scopes.iter().rev().find_map(|s|s.get(n))}
fn number(&self,v:Value)->Result<f64,EngineError>{match v{Value::Number(n)=>Ok(n),Value::Boolean(b)=>Ok(if b{1.0}else{0.0}),Value::Null=>Ok(0.0),Value::String(s)if s.trim().is_empty()=>Ok(0.0),Value::String(s)=>s.trim().parse().map_err(|_|EngineError::Type("cannot convert string to number".into())),Value::Undefined=>Ok(f64::NAN)}}
fn binary(&self,op:&str,a:Value,b:Value)->Result<Value,EngineError>{if op=="+"&&(matches!(a,Value::String(_))||matches!(b,Value::String(_))){return Ok(Value::String(format!("{}{}",a.display(),b.display())))}if op=="==="||op=="!=="{let e=equal(&a,&b);return Ok(Value::Boolean(if op=="==="{e}else{!e}))}if op=="=="||op=="!="{let e=loose(&a,&b,self)?;return Ok(Value::Boolean(if op=="=="{e}else{!e}))}if let(Value::String(x),Value::String(y))=(&a,&b){if matches!(op,"<"|"<="|">"|">="){return Ok(Value::Boolean(match op{"<"=>x<y,"<="=>x<=y,">"=>x>y,">="=>x>=y,_=>false}))}}if op=="&&"{return Ok(if a.truthy(){b}else{a})}if op=="||"{return Ok(if a.truthy(){a}else{b})}let x=self.number(a)?;let y=self.number(b)?;Ok(match op{"+"=>Value::Number(x+y),"-"=>Value::Number(x-y),"*"=>Value::Number(x*y),"/"=>Value::Number(x/y),"%"=>Value::Number(x%y),"**"=>Value::Number(x.powf(y)),"<"=>Value::Boolean(x<y),"<="=>Value::Boolean(x<=y),">"=>Value::Boolean(x>y),">="=>Value::Boolean(x>=y),_=>return Err(EngineError::Syntax(format!("unsupported binary operator {op}")))})}
}
impl EngineError{fn Range(s:String)->Self{Self::Type(s)}}
fn equal(a:&Value,b:&Value)->bool{match(a,b){(Value::Number(x),Value::Number(y))=>x==y,(Value::String(x),Value::String(y))=>x==y,(Value::Boolean(x),Value::Boolean(y))=>x==y,(Value::Null,Value::Null)|(Value::Undefined,Value::Undefined)=>true,_=>false}}
fn loose(a:&Value,b:&Value,r:&Runtime)->Result<bool,EngineError>{if equal(a,b){return Ok(true)}match(a,b){(Value::Null,Value::Undefined)|(Value::Undefined,Value::Null)=>Ok(true),(Value::Number(_),Value::String(_))|(Value::String(_),Value::Number(_))|(Value::Boolean(_),_)|(_,Value::Boolean(_))=>Ok(r.number(a.clone())?==r.number(b.clone())?),_=>Ok(false)}}
#[cfg(test)]mod tests{use super::*;#[test]fn precedence(){assert_eq!(Runtime::new().execute("1+2*(3+4)").unwrap(),Value::Number(15.0))}#[test]fn assignment(){let mut r=Runtime::new();r.execute("let x=4;x=x+1;").unwrap();assert_eq!(r.execute("x").unwrap(),Value::Number(5.0))}#[test]fn if_while(){let mut r=Runtime::new();r.execute("let i=0;while(i<4){i=i+1;}if(i===4){i=8;}").unwrap();assert_eq!(r.execute("i").unwrap(),Value::Number(8.0))}#[test]fn functions_and_return(){let mut r=Runtime::new();assert_eq!(r.execute("function add(a,b){return a+b;} add(3,4);").unwrap(),Value::Number(7.0))}#[test]fn recursive_calls(){let mut r=Runtime::new();assert_eq!(r.execute("function sum(n){if(n<=0){return 0;}return n+sum(n-1);} sum(5);").unwrap(),Value::Number(15.0))}}